def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))

    tests = [fmt([0]), fmt([1]), fmt([-2]), fmt([-3]), fmt([2, 4, 6]), fmt([1, 3, 5]), fmt([1, 2, 3, 4, 6]),
             fmt([-2, 0, 7, -9]), fmt([10**9, -10**9, 10**9 - 1, -10**9 + 1])]
    for _ in range(40):
        n = rng.randint(1, 30)
        tests.append(fmt([rng.randint(-50, 50) for _ in range(n)]))
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(100000)]))
    tests.append(fmt([2 * rng.randint(-5 * 10**8, 5 * 10**8) for _ in range(100000)]))
    tests.append(fmt([2 * rng.randint(-5 * 10**8, 5 * 10**8) + 1 for _ in range(100000)]))
    tests.append(fmt([rng.choice([-10**9, 10**9, -10**9 + 1, 10**9 - 1, 0]) for _ in range(100000)]))
    return tests
